#include "stdafx.h"#include "HcdElementBase.h"struct SONDT_P{#include "PrivateVars/ONDT.h"};class KONDT : public KHcdElementBase  , protected SONDT_P{public:  static IHcdElement *Create();protected:  static void InitParm();  virtual void OnCreated( int domain, LPCSTR pszHmiTagName );  virtual void StepCalc( SStepCalcParams &params );  virtual void OnFilledProjectSettings();};static KHcdFactory _ONDT("ONDT", KONDT::Create);IHcdElement *KONDT::Create(){  return new KONDT;}//////////////////////////////////////////////////////////////////////////#include "_InitInfo.h"DECLARE_PRIVATE_VARSINFO( KONDT, 4 )void KONDT::InitParm(){#include "PrivateVars/ONDT.h"  qsort( s_privateVarInfo, s_kprivateVarInfo, sizeof( SVarInfo ), CompVarInfo );}void KONDT::OnCreated( int domain, LPCSTR pszHmiTagName ){  if( !s_kprivateVarInfo )    InitParm();  m_kPrivateVarsInfo = s_kprivateVarInfo;  m_pPrivateVarsInfo = s_privateVarInfo;  m_pPrivateObject = (BYTE*)this;}void KONDT::OnFilledProjectSettings(){  time = DT;}void KONDT::StepCalc( SStepCalcParams &params ){  if( !RUN )  {    OUTR0 = 0;    time = DT;    return;  }  time -= params.dtS;  if( time > 0 )    return;  OUTR0 = 1;  time = 0;}